-- interview-pcb-diagrams.sql — PCB Layout 六題補圖
-- 這 6 題原本只存在 interview-pcb.sql（bank.js 沒有），所以前端回填吃不到；
-- 已同時在 interview-bank.js 補上 q33-q38（題幹逐字取自本檔），兩條路都能顯示。
--
-- q33  去耦電容擺位（與 q21 同圖）
-- q34  差分對走線 對 vs 錯（與 q23 同圖）
-- q35  回流路徑：完整平面 vs 被切開
-- q36  SW 節點佈局與高頻迴路
-- q37  四層板疊層剖面
-- q38  散熱過孔陣列剖面
--
-- 驗證：瀏覽器重疊實測 = 0；語意/幾何斷言全過（回流繞路高度 80px vs 32px、
--   SW 銅面佔畫布 0.78%、FB 走線不穿過 SW 與 L、疊層 L1-L2 12px < L2-L3 28px、
--   7 個散熱過孔全部落在焊墊 180-340 之內且上下正好接到焊墊與銅面）
-- 用法：Supabase Dashboard → SQL Editor → 全部貼上 → Run。冪等，可重跑。

-- q33：去耦電容擺位（與 q21 同圖）
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="340" viewBox="0 0 520 340" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="340" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">Decoupling: what matters is the loop, not the capacitor</text><text x="135" y="46" fill="#15803d" font-size="12" text-anchor="middle" font-weight="bold">right at the pin</text><text x="395" y="46" fill="#b91c1c" font-size="12" text-anchor="middle" font-weight="bold">parked far away</text><line x1="266" y1="58" x2="266" y2="286" stroke="#cbd5e1" stroke-width="1" stroke-linecap="round"/><g data-sym="rail"><line x1="60" y1="66" x2="60" y2="78" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="52" y1="66" x2="68" y2="66" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="72" y="72" fill="#64748b" font-size="11">VDD plane</text><line x1="60" y1="78" x2="60" y2="100" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="60" y1="100" x2="195" y2="100" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="capacitor"><line x1="100" y1="118" x2="100" y2="135" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="89" y1="135" x2="111" y2="135" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="89" y1="145" x2="111" y2="145" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="100" y1="145" x2="100" y2="162" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="100" y1="100" x2="100" y2="118" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="100" y1="162" x2="100" y2="180" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="100" cy="100" r="2.6" fill="#1f4fd1"/></g><g data-sym="ground"><line x1="100" y1="180" x2="100" y2="194" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="88" y1="194" x2="112" y2="194" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="92" y1="199" x2="108" y2="199" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="96" y1="204" x2="104" y2="204" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="88" y="144" fill="#64748b" font-size="11" text-anchor="end">10u</text><g data-sym="capacitor"><line x1="170" y1="118" x2="170" y2="135" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="159" y1="135" x2="181" y2="135" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="159" y1="145" x2="181" y2="145" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="170" y1="145" x2="170" y2="162" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="170" y1="100" x2="170" y2="118" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="170" y1="162" x2="170" y2="180" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="170" cy="100" r="2.6" fill="#1f4fd1"/></g><g data-sym="ground"><line x1="170" y1="180" x2="170" y2="194" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="158" y1="194" x2="182" y2="194" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="162" y1="199" x2="178" y2="199" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="166" y1="204" x2="174" y2="204" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="158" y="144" fill="#1d2943" font-size="11" text-anchor="end" font-weight="bold">100n</text><g data-sym="ic"><rect x="195" y="78" width="50" height="44" rx="3" fill="#fff" stroke="#1f4fd1" stroke-width="2"/></g><text x="220" y="104" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">IC</text><text x="100" y="222" fill="#64748b" font-size="11" text-anchor="middle">short fat via</text><g data-sym="rail"><line x1="320" y1="66" x2="320" y2="78" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="312" y1="66" x2="328" y2="66" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="332" y="72" fill="#64748b" font-size="11">VDD plane</text><line x1="320" y1="78" x2="320" y2="100" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="320" y1="100" x2="455" y2="100" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="350" cy="100" r="2.6" fill="#1f4fd1"/></g><line x1="350" y1="100" x2="350" y2="168" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="capacitor"><line x1="350" y1="168" x2="350" y2="185" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="339" y1="185" x2="361" y2="185" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="339" y1="195" x2="361" y2="195" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="350" y1="195" x2="350" y2="212" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="350" y1="212" x2="350" y2="226" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="ground"><line x1="350" y1="226" x2="350" y2="240" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="338" y1="240" x2="362" y2="240" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="342" y1="245" x2="358" y2="245" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="346" y1="250" x2="354" y2="250" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="362" y="150" fill="#b91c1c" font-size="11">long stub</text><text x="362" y="166" fill="#b91c1c" font-size="11">adds ESL</text><g data-sym="ic"><rect x="455" y="78" width="50" height="44" rx="3" fill="#fff" stroke="#1f4fd1" stroke-width="2"/></g><text x="480" y="104" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">IC</text><text x="368" y="120" fill="#b91c1c" font-size="11">too far to help</text><text x="10" y="306" fill="#1d2943" font-size="11">100n hugs the pin, 10u sits behind it: plane -> bulk -> ceramic -> pin, never a T-stub.</text><text x="10" y="326" fill="#64748b" font-size="11">One cap per power pin, ground via short and fat - the loop area is the real inductance.</text></svg></div>$vsq$ as box) n
 where question = $q$電源去耦電容怎麼放？$q$;

-- q34：差分對走線 對 vs 錯（與 q23 同圖）
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="340" viewBox="0 0 520 340" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="340" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">Differential pair: what actually keeps the impedance</text><text x="10" y="46" fill="#15803d" font-size="11" font-weight="bold">answer: (C) matched length, fixed gap</text><line x1="258" y1="60" x2="258" y2="250" stroke="#cbd5e1" stroke-width="1" stroke-linecap="round"/><rect x="20" y="92" width="230" height="120" fill="#e2e8f0" stroke="#cbd5e1" stroke-width="1"/><text x="135" y="108" fill="#64748b" font-size="11" text-anchor="middle">continuous reference plane</text><polyline points="30,140 90,140 130,180 240,180" fill="none" stroke="#15803d" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><polyline points="30,156 83.4,156 123.4,196 240,196" fill="none" stroke="#15803d" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><text x="135" y="232" fill="#15803d" font-size="11" text-anchor="middle">same layer, matched length, fixed gap</text><rect x="270" y="92" width="105" height="120" fill="#e2e8f0" stroke="#cbd5e1" stroke-width="1"/><rect x="395" y="92" width="105" height="120" fill="#e2e8f0" stroke="#cbd5e1" stroke-width="1"/><text x="385" y="84" fill="#b91c1c" font-size="11" text-anchor="middle">crossing a split or changing layers</text><polyline points="280,140 490,140" fill="none" stroke="#b91c1c" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><polyline points="280,156 490,156" fill="none" stroke="#b91c1c" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><g data-sym="junction"><circle cx="430" cy="196" r="2.6" fill="#1f4fd1"/></g><g data-sym="junction"><circle cx="452" cy="196" r="2.6" fill="#1f4fd1"/></g><text x="441" y="228" fill="#b91c1c" font-size="11" text-anchor="middle">vias to another layer</text><text x="10" y="286" fill="#1d2943" font-size="11">(C) equal length kills skew and a fixed gap keeps the coupling, so Zdiff stays put.</text><text x="10" y="306" fill="#64748b" font-size="11">(A) and (D) both break the reference: split layers or no plane means no controlled Z0.</text><text x="10" y="326" fill="#64748b" font-size="11">(B) is a myth - what matters is the plane underneath, not the copper beside the pair.</text></svg></div>$vsq$ as box) n
 where question = $q$高速差分對走線要點？$q$;

-- q35：回流路徑：完整平面 vs 被切開
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="340" viewBox="0 0 520 340" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="340" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">Return current takes the smallest loop, not the shortest path</text><line x1="258" y1="60" x2="258" y2="250" stroke="#cbd5e1" stroke-width="1" stroke-linecap="round"/><text x="135" y="46" fill="#15803d" font-size="12" text-anchor="middle" font-weight="bold">solid plane</text><text x="390" y="46" fill="#b91c1c" font-size="12" text-anchor="middle" font-weight="bold">plane with a slot</text><path d="M 30 116 H 240 V 152 H 30 V 116" fill="none" stroke="#16a34a" stroke-width="9" stroke-opacity="0.30" stroke-linecap="round" stroke-linejoin="round"/><polyline points="30,116 240,116" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><rect x="20" y="146" width="230" height="12" fill="#1f4fd1" opacity="0.85" stroke="#1f4fd1" stroke-width="1"/><text x="135" y="104" fill="#64748b" font-size="11" text-anchor="middle">signal</text><text x="135" y="184" fill="#15803d" font-size="11" text-anchor="middle">return sits right under it</text><text x="135" y="204" fill="#64748b" font-size="11" text-anchor="middle">small loop = low EMI</text><path d="M 280 116 H 490 V 152 H 430 V 230 H 340 V 152 H 280 V 116" fill="none" stroke="#b91c1c" stroke-width="9" stroke-opacity="0.30" stroke-linecap="round" stroke-linejoin="round"/><polyline points="280,116 490,116" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><rect x="270" y="146" width="60" height="12" fill="#1f4fd1" opacity="0.85" stroke="#1f4fd1" stroke-width="1"/><rect x="440" y="146" width="60" height="12" fill="#1f4fd1" opacity="0.85" stroke="#1f4fd1" stroke-width="1"/><text x="385" y="104" fill="#64748b" font-size="11" text-anchor="middle">signal</text><text x="385" y="140" fill="#b91c1c" font-size="11" text-anchor="middle">slot</text><text x="385" y="246" fill="#b91c1c" font-size="11" text-anchor="middle">return has to go around</text><text x="10" y="286" fill="#1d2943" font-size="11">Above a few MHz the return hugs the trace, so the loop is trace-to-plane spacing.</text><text x="10" y="306" fill="#64748b" font-size="11">Slot the plane and the loop opens up: EMI, crosstalk and ringing all follow it.</text><text x="10" y="326" fill="#64748b" font-size="11">Changing layers? Put a stitching via next to the signal via or the loop opens again.</text></svg></div>$vsq$ as box) n
 where question = $q$為什麼要完整的地平面（return path）？$q$;

-- q36：SW 節點佈局與高頻迴路
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="340" viewBox="0 0 520 340" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="340" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">Switch-node layout: loop, copper, feedback</text><path d="M 40 120 H 75 V 150 H 200 V 240 H 40 V 120" fill="none" stroke="#f59e0b" stroke-width="9" stroke-opacity="0.30" stroke-linecap="round" stroke-linejoin="round"/><g data-sym="rail"><line x1="40" y1="108" x2="40" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="32" y1="108" x2="48" y2="108" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="40" y="98" fill="#b91c1c" font-size="11" text-anchor="middle" font-weight="bold">VIN</text><line x1="40" y1="120" x2="75" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="40" cy="120" r="2.6" fill="#1f4fd1"/></g><g data-sym="capacitor"><line x1="40" y1="146" x2="40" y2="163" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="29" y1="163" x2="51" y2="163" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="29" y1="173" x2="51" y2="173" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="40" y1="173" x2="40" y2="190" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="40" y1="120" x2="40" y2="146" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="40" y1="190" x2="40" y2="240" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="28" y="166" fill="#64748b" font-size="11" text-anchor="end">Cin</text><g data-sym="ic"><rect x="75" y="95" width="90" height="110" rx="3" fill="#fff" stroke="#1f4fd1" stroke-width="2"/></g><text x="120" y="146" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">Buck IC</text><text x="120" y="164" fill="#64748b" font-size="11" text-anchor="middle">controller</text><line x1="165" y1="150" x2="206" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="185" y="142" fill="#b91c1c" font-size="11" text-anchor="middle" font-weight="bold">SW</text><text x="215" y="128" fill="#64748b" font-size="11">small SW copper</text><g data-sym="inductor"><line x1="206" y1="150" x2="212" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><path d="M 212 150 A 4.5 4.5 0 1 1 221 150 A 4.5 4.5 0 1 1 230 150 A 4.5 4.5 0 1 1 239 150 A 4.5 4.5 0 1 1 248 150" fill="none" stroke="#1f4fd1" stroke-width="2"/><line x1="248" y1="150" x2="254" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="230" y="178" fill="#1d2943" font-size="11" text-anchor="middle">L</text><line x1="254" y1="150" x2="340" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="290" cy="150" r="2.6" fill="#1f4fd1"/></g><g data-sym="junction"><circle cx="200" cy="150" r="2.6" fill="#1f4fd1"/></g><text x="346" y="154" fill="#1d2943" font-size="11" font-weight="bold">VOUT</text><g data-sym="diode"><line x1="200" y1="174" x2="200" y2="188" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="200" y1="204" x2="200" y2="218" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polygon points="192,204 208,204 200,188" fill="none" stroke="#1f4fd1" stroke-width="2"/><line x1="192" y1="188" x2="208" y2="188" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="200" y1="150" x2="200" y2="174" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="200" y1="218" x2="200" y2="240" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="212" y="200" fill="#b91c1c" font-size="11" font-weight="bold">D</text><g data-sym="capacitor"><line x1="290" y1="174" x2="290" y2="191" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="279" y1="191" x2="301" y2="191" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="279" y1="201" x2="301" y2="201" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="290" y1="201" x2="290" y2="218" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="290" y1="150" x2="290" y2="174" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="290" y1="218" x2="290" y2="240" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="302" y="196" fill="#64748b" font-size="11">Cout</text><line x1="40" y1="240" x2="290" y2="240" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="200" cy="240" r="2.6" fill="#1f4fd1"/></g><g data-sym="junction"><circle cx="245" cy="240" r="2.6" fill="#1f4fd1"/></g><g data-sym="ground"><line x1="245" y1="240" x2="245" y2="254" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="233" y1="254" x2="257" y2="254" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="237" y1="259" x2="253" y2="259" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="241" y1="264" x2="249" y2="264" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="258" y="258" fill="#64748b" font-size="11">single-point GND</text><text x="60" y="230" fill="#b45309" font-size="11">keep this loop small</text><line x1="340" y1="150" x2="340" y2="74" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="340" y1="74" x2="110" y2="74" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="110" y1="74" x2="110" y2="95" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="225" y="66" fill="#b45309" font-size="11" text-anchor="middle">feedback routed away from SW</text><text x="10" y="300" fill="#1d2943" font-size="11">The hot loop is Cin -> IC -> SW -> D -> back to Cin. Its area is the EMI antenna.</text><text x="10" y="320" fill="#64748b" font-size="11">Keep SW copper small, feedback far from it, and let the grounds meet at one point.</text></svg></div>$vsq$ as box) n
 where question = $q$開關電源（SW 節點）佈局注意？$q$;

-- q37：四層板疊層剖面
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="340" viewBox="0 0 520 340" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="340" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">Four-layer stackup: every signal next to a plane</text><rect x="40" y="98" width="240" height="32" fill="#e2e8f0" stroke="#cbd5e1" stroke-width="1"/><rect x="40" y="142" width="240" height="56" fill="#e2e8f0" stroke="#cbd5e1" stroke-width="1"/><rect x="40" y="210" width="240" height="32" fill="#e2e8f0" stroke="#cbd5e1" stroke-width="1"/><rect x="40" y="86" width="240" height="12" fill="#1f4fd1" opacity="0.85" stroke="#1f4fd1" stroke-width="1"/><text x="292" y="95" fill="#1d2943" font-size="11" font-weight="bold">L1  signal</text><text x="292" y="111" fill="#64748b" font-size="11">high-speed lives here</text><rect x="40" y="130" width="240" height="12" fill="#1f4fd1" opacity="0.85" stroke="#1f4fd1" stroke-width="1"/><text x="292" y="139" fill="#15803d" font-size="11" font-weight="bold">L2  GND</text><text x="292" y="155" fill="#64748b" font-size="11">solid, no splits</text><rect x="40" y="198" width="240" height="12" fill="#1f4fd1" opacity="0.85" stroke="#1f4fd1" stroke-width="1"/><text x="292" y="207" fill="#1d2943" font-size="11" font-weight="bold">L3  power</text><text x="292" y="223" fill="#64748b" font-size="11">planes, not traces</text><rect x="40" y="242" width="240" height="12" fill="#1f4fd1" opacity="0.85" stroke="#1f4fd1" stroke-width="1"/><text x="292" y="251" fill="#1d2943" font-size="11" font-weight="bold">L4  signal</text><text x="292" y="267" fill="#64748b" font-size="11">slow stuff, connectors</text><text x="160" y="118" fill="#64748b" font-size="11" text-anchor="middle">prepreg 4mil</text><text x="160" y="174" fill="#64748b" font-size="11" text-anchor="middle">core</text><text x="160" y="230" fill="#64748b" font-size="11" text-anchor="middle">prepreg 4mil</text><text x="10" y="286" fill="#1d2943" font-size="11">Signal-GND-PWR-Signal: both signal layers get a plane one prepreg away, so Z0 and</text><text x="10" y="306" fill="#1d2943" font-size="11">the return path are defined. Thin prepreg sets the impedance you can actually hit.</text><text x="10" y="326" fill="#64748b" font-size="11">Keep the GND-PWR core thin if you want plane capacitance out of the stackup.</text></svg></div>$vsq$ as box) n
 where question = $q$四層板疊層怎麼選？$q$;

-- q38：散熱過孔陣列剖面
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="340" viewBox="0 0 520 340" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="340" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">Getting heat out of a PCB: vias into copper</text><g data-sym="ic"><rect x="85" y="76" width="130" height="40" rx="3" fill="#fff" stroke="#1f4fd1" stroke-width="2"/></g><text x="150" y="100" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">power part</text><rect x="85" y="120" width="130" height="10" fill="#1f4fd1" stroke="#1f4fd1" stroke-width="1"/><text x="260" y="129" fill="#64748b" font-size="11">thermal pad</text><rect x="40" y="150" width="250" height="60" fill="#e2e8f0" stroke="#cbd5e1" stroke-width="1"/><rect x="86" y="150" width="8" height="60" fill="#1f4fd1" opacity="0.85" stroke="#1f4fd1" stroke-width="1"/><rect x="110" y="150" width="8" height="60" fill="#1f4fd1" opacity="0.85" stroke="#1f4fd1" stroke-width="1"/><rect x="134" y="150" width="8" height="60" fill="#1f4fd1" opacity="0.85" stroke="#1f4fd1" stroke-width="1"/><rect x="158" y="150" width="8" height="60" fill="#1f4fd1" opacity="0.85" stroke="#1f4fd1" stroke-width="1"/><rect x="182" y="150" width="8" height="60" fill="#1f4fd1" opacity="0.85" stroke="#1f4fd1" stroke-width="1"/><rect x="206" y="150" width="8" height="60" fill="#1f4fd1" opacity="0.85" stroke="#1f4fd1" stroke-width="1"/><rect x="40" y="210" width="250" height="12" fill="#1f4fd1" opacity="0.85" stroke="#1f4fd1" stroke-width="1"/><text x="260" y="176" fill="#64748b" font-size="11">via array</text><text x="165" y="240" fill="#64748b" font-size="11" text-anchor="middle">inner / bottom copper spreads it</text><line x1="20" y1="262" x2="270" y2="262" stroke="#b45309" stroke-width="2" stroke-linecap="round"/><polygon points="270,262 260,257 260,267" fill="#b45309" stroke="#b45309" stroke-width="1"/><text x="280" y="266" fill="#b45309" font-size="11">airflow</text><text x="10" y="296" fill="#1d2943" font-size="11">Vias under the pad are the low-resistance path into the planes: more vias, more copper,</text><text x="10" y="316" fill="#64748b" font-size="11">lower RthJA. Spread the hot parts out so none of them sits in another one is wake.</text></svg></div>$vsq$ as box) n
 where question = $q$PCB 散熱怎麼處理？$q$;

-- 驗收：六列 zh 都要 t（PCB 題原本沒有 ja/ko 譯文，null 是正常的）
select left(question, 20) as q, answer like '%<svg%' as zh, answer_en like '%<svg%' as en
  from public.interview_questions
 where category = 'PCB Layout' order by id;
